34	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
35	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.PetDto;
37	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.VisitDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
40	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
41	import org.springframework.samples.petclinic.rest.validation.CityCapacityExceededException;
42	import org.springframework.samples.petclinic.rest.validation.DailyOwnerLimitExceededException;
43	import org.springframework.samples.petclinic.rest.validation.DisposableEmailException;
44	import org.springframework.samples.petclinic.rest.validation.DisposableEmailValidator;
45	import org.springframework.samples.petclinic.rest.validation.DuplicateIdentityException;
46	import org.springframework.samples.petclinic.rest.validation.EmailNormalizer;
47	import org.springframework.samples.petclinic.rest.validation.FutureRegistrationDateException;
48	import org.springframework.samples.petclinic.rest.validation.InvalidPostcodeException;
49	import org.springframework.samples.petclinic.rest.validation.MissingOwnerFieldsException;
50	import org.springframework.samples.petclinic.rest.validation.PostcodeValidator;
51	import org.springframework.samples.petclinic.rest.validation.OwnerFieldsValidator;
52	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
53	import org.springframework.samples.petclinic.service.ClinicService;
54	import org.springframework.samples.petclinic.service.IdempotencyKeyStore;
55	import org.springframework.samples.petclinic.service.OwnerAuditor;
56	import org.springframework.samples.petclinic.util.HouseholdIdGenerator;
57	import org.springframework.samples.petclinic.util.RegistrationDatePolicy;
58	import org.springframework.security.access.prepost.PreAuthorize;
59	import org.springframework.web.bind.annotation.CrossOrigin;
60	import org.springframework.web.bind.annotation.RequestMapping;
61	import org.springframework.web.bind.annotation.RestController;
62	import org.springframework.web.util.UriComponentsBuilder;
63	
64	import jakarta.transaction.Transactional;
65	
66	/**
67	 * @author Vitaliy Fedoriv
68	 */
69	
70	@RestController
71	@CrossOrigin(exposedHeaders = "errors, content-type")
72	@RequestMapping("/api")
73	public class OwnerRestControllerV1 implements OwnersApi {
74	
75	    /**
76	     * Maximum number of owners a single city may hold. A create request whose city already contains
77	     * this many owners is rejected as a conflict.
78	     */
79	    static final int MAX_OWNERS_PER_CITY = 50;
80	
81	    /**
82	     * Maximum number of owners that may be registered on a single day. A create request whose
83	     * registration date already holds this many owners is rejected with 429 Too Many Requests.
84	     */
85	    static final int MAX_OWNERS_PER_DAY = 100;
86	
87	    /**
88	     * Number of owners that may be registered on the current business day before a create/read
89	     * response flags {@code bulkSignupWarning}. Once more than this many owners exist for the day,
90	     * the warning is raised.
91	     */
92	    static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
93	
94	    private final ClinicService clinicService;
95	
96	    private final OwnerMapper ownerMapper;
97	
98	    private final PetMapper petMapper;
99	
100	    private final VisitMapper visitMapper;
101	
102	    private final OwnerAuditor ownerAuditor;
103	
104	    private final IdempotencyKeyStore idempotencyKeyStore;
105	
106	    public OwnerRestControllerV1(ClinicService clinicService,
107	                                 OwnerMapper ownerMapper,
108	                                 PetMapper petMapper,
109	                                 VisitMapper visitMapper,
110	                                 OwnerAuditor ownerAuditor,
111	                                 IdempotencyKeyStore idempotencyKeyStore) {
112	        this.clinicService = clinicService;
113	        this.ownerMapper = ownerMapper;
114	        this.petMapper = petMapper;
115	        this.visitMapper = visitMapper;
116	        this.ownerAuditor = ownerAuditor;
117	        this.idempotencyKeyStore = idempotencyKeyStore;
118	    }
119	
120	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
121	    @Override
122	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
123	        Collection<Owner> owners;
124	        if (lastName != null) {
125	            owners = this.clinicService.findOwnerByLastName(lastName);
126	        } else {
127	            owners = this.clinicService.findAllOwners();
128	        }
129	        if (owners.isEmpty()) {
130	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
131	        }
132	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
133	    }
134	
135	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
136	    @Override
137	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
138	        Owner owner = this.clinicService.findOwnerById(ownerId);
139	        if (owner == null) {
140	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
141	        }
142	        return new ResponseEntity<>(toOwnerDtoWithBulkSignupWarning(owner), HttpStatus.OK);
143	    }
144	
145	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
146	    @Override
147	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
148	        if (idempotencyKey != null) {
149	            Optional<OwnerDto> existing = idempotencyKeyStore.findOwnerId(idempotencyKey)
150	                .map(this.clinicService::findOwnerById)
151	                .map(this::toOwnerDtoWithBulkSignupWarning);
152	            if (existing.isPresent()) {
153	                return new ResponseEntity<>(existing.get(), HttpStatus.OK);
154	            }
155	        }
156	        resolveAddress(ownerFieldsDto);
157	        List<String> missingFields = OwnerFieldsValidator.findMissingFields(ownerFieldsDto);
158	        if (!missingFields.isEmpty()) {
159	            throw new MissingOwnerFieldsException(missingFields);
160	        }
161	        HttpHeaders headers = new HttpHeaders();
162	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
163	        if (!PostcodeValidator.isValidForCity(owner.getCity(), owner.getPostcode())) {
164	            throw new InvalidPostcodeException(owner.getPostcode(), owner.getCity());
165	        }
166	        if (this.clinicService.countOwnersByCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
167	            throw new CityCapacityExceededException(owner.getCity());
168	        }
169	        if (RegistrationDatePolicy.isAfterServerDate(owner.getRegistrationDate())) {
170	            throw new FutureRegistrationDateException(owner.getRegistrationDate());
171	        }
172	        LocalDate registrationDate = RegistrationDatePolicy.effectiveDate(owner.getRegistrationDate());
173	        if (this.clinicService.countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
174	            throw new DailyOwnerLimitExceededException(registrationDate);
175	        }
176	        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
177	        owner.setEmail(EmailNormalizer.normalize(owner.getEmail()));
178	        if (DisposableEmailValidator.isDisposable(owner.getEmail())) {
179	            throw new DisposableEmailException(owner.getEmail());
180	        }
181	        // The household is keyed on (last name, postcode): the id is deterministic, so owners with
182	        // the same last name and postcode share it automatically.
183	        owner.setHouseholdId(HouseholdIdGenerator.generate(owner.getLastName(), owner.getPostcode()));
184	        boolean declaredHouseholdMember = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
185	        owner.setDeclaredHouseholdMember(declaredHouseholdMember);
186	        // A second owner in an existing household is a duplicate, unless it declares shared
187	        // membership — in which case it is created as a known household member.
188	        if (!declaredHouseholdMember && this.clinicService.isHouseholdDuplicate(owner)) {
189	            throw new DuplicateIdentityException(owner.getIdentityKey());
190	        }
191	        this.clinicService.saveOwner(owner);
192	        this.ownerAuditor.ownerCreated(owner);
193	        if (idempotencyKey != null) {
194	            this.idempotencyKeyStore.remember(idempotencyKey, owner.getId());
195	        }
196	        OwnerDto ownerDto = toOwnerDtoWithBulkSignupWarning(owner);
197	        headers.setLocation(UriComponentsBuilder.newInstance()
198	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
199	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
200	    }
201	
202	    /**
203	     * Normalize the submitted address form and resolve the canonical stored {@code address}.
204	     * Whichever fields are supplied are normalized: the structured {@code addressLine1}/
205	     * {@code addressLine2} are kept (blank lines dropped to {@code null}), and {@code address}
206	     * is set to the composed structured address when {@code addressLine1} is present, otherwise
207	     * to the normalized flat {@code address}. Everything downstream reads the resolved
208	     * {@code address}, so it reflects the structured fields when present and the flat address
209	     * otherwise.
210	     */
211	    private void resolveAddress(OwnerFieldsDto ownerFieldsDto) {
212	        String line1 = AddressNormalizer.normalize(ownerFieldsDto.getAddressLine1());
213	        String line2 = AddressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
214	        ownerFieldsDto.setAddressLine1(line1.isEmpty() ? null : line1);
215	        ownerFieldsDto.setAddressLine2(line2.isEmpty() ? null : line2);
216	        if (ownerFieldsDto.getAddressLine1() != null) {
217	            ownerFieldsDto.setAddress(
218	                AddressNormalizer.compose(ownerFieldsDto.getAddressLine1(), ownerFieldsDto.getAddressLine2()));
219	        } else {
220	            ownerFieldsDto.setAddress(AddressNormalizer.normalize(ownerFieldsDto.getAddress()));
221	        }
222	    }
223	
224	    /**
225	     * Map an owner to its DTO and stamp {@code bulkSignupWarning}, which reflects whether more than
226	     * {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been registered on the current
227	     * business day.
228	     */
229	    private OwnerDto toOwnerDtoWithBulkSignupWarning(Owner owner) {
230	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
231	        LocalDate today = RegistrationDatePolicy.effectiveDate(null);
232	        ownerDto.setBulkSignupWarning(
233	            this.clinicService.countOwnersRegisteredOn(today) > BULK_SIGNUP_WARNING_THRESHOLD);
234	        return ownerDto;
235	    }
236	
237	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
238	    @Override
239	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
240	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
241	        if (currentOwner == null) {
242	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
243	        }
244	        currentOwner.setAddress(ownerFieldsDto.getAddress());
245	        currentOwner.setCity(ownerFieldsDto.getCity());
246	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
247	        currentOwner.setLastName(ownerFieldsDto.getLastName());
248	        currentOwner.setTelephone(TelephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
249	        currentOwner.setEmail(EmailNormalizer.normalize(ownerFieldsDto.getEmail()));
250	        this.clinicService.saveOwner(currentOwner);
251	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
252	    }
253	
254	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
255	    @Transactional
256	    @Override
257	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
258	        Owner owner = this.clinicService.findOwnerById(ownerId);
259	        if (owner == null) {
260	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
261	        }
262	        this.clinicService.deleteOwner(owner);
263	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
264	    }
265	
266	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
267	    @Override
268	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
269	        Owner owner = this.clinicService.findOwnerById(ownerId);
270	        if (owner == null) {
271	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
272	        }
273	        HttpHeaders headers = new HttpHeaders();
274	        Pet pet = petMapper.toPet(petFieldsDto);
275	        owner.setId(ownerId);
276	        pet.setOwner(owner);
277	        pet.getType().setName(null);
278	        this.clinicService.savePet(pet);
279	        PetDto petDto = petMapper.toPetDto(pet);
280	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
281	            .buildAndExpand(pet.getId()).toUri());
282	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
283	    }
284	
285	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
286	    @Override
287	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
288	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
289	        if (currentOwner != null) {
290	            Pet currentPet = this.clinicService.findPetById(petId);
291	            if (currentPet != null) {
292	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
293	                currentPet.setName(petFieldsDto.getName());
294	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
295	                this.clinicService.savePet(currentPet);
296	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
297	            }
298	        }
299	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
300	    }
301	
302	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
303	    @Override
304	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
305	        HttpHeaders headers = new HttpHeaders();
306	        Visit visit = visitMapper.toVisit(visitFieldsDto);
307	        Pet pet = new Pet();
308	        pet.setId(petId);
309	        visit.setPet(pet);
310	        this.clinicService.saveVisit(visit);
311	        VisitDto visitDto = visitMapper.toVisitDto(visit);
312	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
313	            .buildAndExpand(visit.getId()).toUri());
314	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
315	    }
316	
317	
318	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
319	    @Override
320	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
321	        Owner owner = this.clinicService.findOwnerById(ownerId);
322	        if (owner != null) {
323	            Pet pet = owner.getPet(petId);
324	            if (pet != null) {
325	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
326	            }
327	        }
328	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
329	    }
330	}
