16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	import org.springframework.samples.petclinic.util.FiscalYear;
20	import org.springframework.samples.petclinic.util.Luhn;
21	import org.springframework.samples.petclinic.util.RegistrationDatePolicy;
22	
23	import jakarta.persistence.*;
24	import jakarta.validation.constraints.NotEmpty;
25	import jakarta.validation.constraints.Pattern;
26	
27	import java.time.LocalDate;
28	import java.util.*;
29	
30	/**
31	 * Simple JavaBean domain object representing an owner.
32	 *
33	 * @author Ken Krebs
34	 * @author Juergen Hoeller
35	 * @author Sam Brannen
36	 * @author Michael Isvy
37	 */
38	@Entity
39	@Table(name = "owners")
40	public class Owner extends Person {
41	    @Column(name = "title")
42	    private String title;
43	
44	    @Column(name = "address")
45	    @NotEmpty
46	    private String address;
47	
48	    @Column(name = "address_line1")
49	    private String addressLine1;
50	
51	    @Column(name = "address_line2")
52	    private String addressLine2;
53	
54	    @Column(name = "city")
55	    @NotEmpty
56	    private String city;
57	
58	    @Column(name = "postcode")
59	    private String postcode;
60	
61	    @Column(name = "telephone")
62	    @NotEmpty
63	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
64	    private String telephone;
65	
66	    @Column(name = "email")
67	    private String email;
68	
69	    @Column(name = "birth_date")
70	    private LocalDate birthDate;
71	
72	    @Column(name = "registration_date")
73	    private LocalDate registrationDate;
74	
75	    @Column(name = "customer_code")
76	    private String customerCode;
77	
78	    @Column(name = "household_id")
79	    private String householdId;
80	
81	    @Column(name = "namesake_count")
82	    private Integer namesakeCount;
83	
84	    @Column(name = "household_size")
85	    private Integer householdSize;
86	
87	    @Column(name = "possible_duplicate")
88	    private Boolean possibleDuplicate;
89	
90	    @Column(name = "possible_duplicate_of")
91	    private Integer possibleDuplicateOf;
92	
93	    @Column(name = "deleted", nullable = false)
94	    private boolean deleted;
95	
96	    /**
97	     * Whether this owner was knowingly created into a shared household (the request declared shared
98	     * membership). A declared member is not treated as a suspected duplicate. Set per request and
99	     * never persisted.
100	     */
101	    @Transient
102	    private boolean declaredHouseholdMember;
103	
104	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
105	    private Set<Pet> pets;
106	
107	    /**
108	     * Resolve the registration date at creation time: default it to the server's
109	     * current date when none was supplied, and roll a weekend date forward to the
110	     * next business day so every value derived from it (such as the membership
111	     * number's year segment) uses the adjusted date.
112	     */
113	    @PrePersist
114	    private void resolveRegistrationDate() {
115	        this.registrationDate = RegistrationDatePolicy.effectiveDate(this.registrationDate);
116	    }
117	
118	    public String getTitle() {
119	        return this.title;
120	    }
121	
122	    public void setTitle(String title) {
123	        this.title = title;
124	    }
125	
126	    /**
127	     * The owner's salutation: the {@link #title} followed by a space and the
128	     * {@linkplain #getLastName() last name} (e.g. {@code "DR Who"}), or just the
129	     * last name when no title is on file.
130	     */
131	    public String getSalutation() {
132	        if (this.title == null || this.title.isEmpty()) {
133	            return getLastName();
134	        }
135	        return this.title + " " + getLastName();
136	    }
137	
138	    public String getAddress() {
139	        return this.address;
140	    }
141	
142	    public void setAddress(String address) {
143	        this.address = address;
144	    }
145	
146	    public String getAddressLine1() {
147	        return this.addressLine1;
148	    }
149	
150	    public void setAddressLine1(String addressLine1) {
151	        this.addressLine1 = addressLine1;
152	    }
153	
154	    public String getAddressLine2() {
155	        return this.addressLine2;
156	    }
157	
158	    public void setAddressLine2(String addressLine2) {
159	        this.addressLine2 = addressLine2;
160	    }
161	
162	    public String getCity() {
163	        return this.city;
164	    }
165	
166	    public void setCity(String city) {
167	        this.city = city;
168	    }
169	
170	    public String getPostcode() {
171	        return this.postcode;
172	    }
173	
174	    public void setPostcode(String postcode) {
175	        this.postcode = postcode;
176	    }
177	
178	    /**
179	     * The owner's locality: the region component of its {@link #customerCode}
180	     * identity (see {@link CustomerCode}), or {@code null} when no customer code
181	     * is assigned. The region was derived from the owner's postcode and city when
182	     * the identity was minted, so the locality now follows the identity rather than
183	     * being recomputed from the current city and postcode.
184	     */
185	    public String getLocality() {
186	        return CustomerCode.regionOf(this.customerCode);
187	    }
188	
189	    /**
190	     * The owner's timezone: the IANA name for its {@linkplain #getLocality()
191	     * locality}, from the fixed region-to-timezone table (see
192	     * {@link RegionTimezone}), or {@code null} when the locality is absent or has
193	     * no known timezone.
194	     */
195	    public String getTimezone() {
196	        return RegionTimezone.zoneFor(getLocality());
197	    }
198	
199	    public String getTelephone() {
200	        return this.telephone;
201	    }
202	
203	    public void setTelephone(String telephone) {
204	        this.telephone = telephone;
205	    }
206	
207	    public String getEmail() {
208	        return this.email;
209	    }
210	
211	    public void setEmail(String email) {
212	        this.email = email;
213	    }
214	
215	    public LocalDate getBirthDate() {
216	        return this.birthDate;
217	    }
218	
219	    public void setBirthDate(LocalDate birthDate) {
220	        this.birthDate = birthDate;
221	    }
222	
223	    /**
224	     * The owner's {@link AgeBand age band} on the {@link #registrationDate}, derived
225	     * from the {@link #birthDate}, or {@code null} when no birth date is on file.
226	     */
227	    public AgeBand getAgeBand() {
228	        return AgeBand.on(this.birthDate, this.registrationDate);
229	    }
230	
231	    public LocalDate getRegistrationDate() {
232	        return this.registrationDate;
233	    }
234	
235	    public void setRegistrationDate(LocalDate registrationDate) {
236	        this.registrationDate = registrationDate;
237	    }
238	
239	    public String getCustomerCode() {
240	        return this.customerCode;
241	    }
242	
243	    public void setCustomerCode(String customerCode) {
244	        this.customerCode = customerCode;
245	    }
246	
247	    /**
248	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'}
249	     * where {@code YY} is the two-digit segment of the {@linkplain #getFiscalYear()
250	     * fiscal year} of the {@link #registrationDate} (e.g. {@code "NSW-3F2A9C1D-M27"}
251	     * for a registration in fiscal year 2027). Derived from the owner's own fields.
252	     */
253	    public String getMembershipNumber() {
254	        if (this.customerCode == null || this.registrationDate == null) {
255	            return null;
256	        }
257	        return String.format("%s-M%02d", this.customerCode, FiscalYear.yearSegment(this.registrationDate));
258	    }
259	
260	    /**
261	     * The owner's fiscal year: the {@code 'FY<YY>'} label (e.g. {@code "FY27"}) of the
262	     * fiscal year the {@link #registrationDate} falls in, where a fiscal year starts on
263	     * 1 July and is numbered by the calendar year in which it ends (see
264	     * {@link FiscalYear}). {@code null} when no registration date is on file.
265	     */
266	    public String getFiscalYear() {
267	        return FiscalYear.label(this.registrationDate);
268	    }
