271	     * The Luhn check digit (0-9) computed over the digits of the
272	     * {@link #customerCode}, or {@code null} when no customer code is assigned.
273	     */
274	    public Integer getCheckDigit() {
275	        if (this.customerCode == null) {
276	            return null;
277	        }
278	        return Luhn.checkDigit(this.customerCode);
279	    }
