285	    public void setHouseholdId(String householdId) {
286	        this.householdId = householdId;
287	    }
288	
289	    /**
290	     * The owner's identity key: the single derived value used to detect duplicate owners. It is the
291	     * normalized telephone, the (lower-cased) email or an empty string when absent, and the
292	     * household id or an empty string when absent, joined with {@code '|'} (e.g.
293	     * {@code "+61412345678|jo@example.com|3F2A9C1D4B6E8071"}). Two owners are the same person only
294	     * when their whole identity keys are equal; because the telephone is part of the key, household
295	     * members with different telephones have different keys.
296	     */
297	    public String getIdentityKey() {
298	        return String.join("|",
299	            this.telephone == null ? "" : this.telephone,
300	            this.email == null ? "" : this.email,
301	            this.householdId == null ? "" : this.householdId);
302	    }
303	
304	    /** Tenure, in elapsed fiscal years, at or beyond which an owner earns the tenure membership points. */
305	    private static final long TENURE_FISCAL_YEARS_FOR_POINTS = 1;
306	
307	    /** Household size at or above which an owner earns the household membership points. */
308	    private static final int HOUSEHOLD_SIZE_FOR_POINTS = 3;
309	
310	    /**
311	     * The owner's membership points, a score derived from the owner's own
312	     * fields. Starts at {@code 0}, gains {@code 2} when a contact email is on
313	     * file, gains {@code 1} when the owner has no namesakes, gains {@code 2}
314	     * when the owner belongs to a household of {@value #HOUSEHOLD_SIZE_FOR_POINTS}
315	     * or more, and gains {@code 3} when the owner's {@link #getTenureFiscalYears()
316	     * tenure} reaches {@value #TENURE_FISCAL_YEARS_FOR_POINTS} or more elapsed fiscal years.
317	     */
318	    public Integer getMembershipPoints() {
319	        int points = 0;
320	        boolean hasEmail = this.email != null && !this.email.isEmpty();
321	        if (hasEmail) {
322	            points += 2;
323	        }
324	        boolean noNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
325	        if (noNamesakes) {
326	            points += 1;
327	        }
328	        boolean largeHousehold = this.householdSize != null && this.householdSize >= HOUSEHOLD_SIZE_FOR_POINTS;
329	        if (largeHousehold) {
330	            points += 2;
331	        }
332	        Long tenureFiscalYears = getTenureFiscalYears();
333	        if (tenureFiscalYears != null && tenureFiscalYears >= TENURE_FISCAL_YEARS_FOR_POINTS) {
334	            points += 3;
335	        }
336	        return points;
337	    }
338	
339	    /**
340	     * The owner's membership level, a number from 1 to 4 mapped from the owner's
341	     * {@link #getMembershipPoints() membership points}: {@code 1} for 0-1 points,
342	     * {@code 2} for 2-3, {@code 3} for 4-5 and {@code 4} for 6 or more.
343	     */
344	    public Integer getMembershipLevel() {
345	        int points = getMembershipPoints();
346	        if (points <= 1) {
347	            return 1;
348	        }
349	        if (points <= 3) {
350	            return 2;
351	        }
352	        if (points <= 5) {
353	            return 3;
354	        }
355	        return 4;
356	    }
357	
358	    /**
359	     * The owner's tenure: the number of whole fiscal years elapsed from the
360	     * {@link #registrationDate} to the server's current date — the count of 1 July
361	     * boundaries crossed between them (see {@link FiscalYear}), or {@code null} when no
362	     * registration date is on file. Zero while both dates fall in the same fiscal year,
363	     * and never negative for a registration date that is today or earlier.
364	     */
365	    public Long getTenureFiscalYears() {
366	        if (this.registrationDate == null) {
367	            return null;
368	        }
369	        return FiscalYear.elapsedYears(this.registrationDate, LocalDate.now());
370	    }
