474	    /**
475	     * Return the Pet with the given name, or null if none found for this Owner.
476	     *
477	     * @param name to test
478	     * @return true if pet name is already in use
479	     */
480	    public Pet getPet(String name) {
481	        return getPet(name, false);
482	    }
