484	    /**
485	     * Return the Pet with the given name, or null if none found for this Owner.
486	     *
487	     * @param name to test
488	     * @return true if pet name is already in use
489	     */
490	    public Pet getPet(String name, boolean ignoreNew) {
491	        name = name.toLowerCase();
492	        for (Pet pet : getPetsInternal()) {
493	            if (!ignoreNew || !pet.isNew()) {
494	                String compName = pet.getName();
495	                compName = compName.toLowerCase();
496	                if (compName.equals(name)) {
497	                    return pet;
498	                }
499	            }
500	        }
501	        return null;
502	    }
