508	    @Override
509	    public String toString() {
510	        return new ToStringCreator(this)
511	
512	            .append("id", this.getId())
513	            .append("new", this.isNew())
514	            .append("lastName", this.getLastName())
515	            .append("firstName", this.getFirstName())
516	            .append("address", this.address)
517	            .append("city", this.city)
518	            .append("telephone", this.telephone)
519	            .append("email", this.email)
520	            .toString();
521	    }
