255	            owner.setNamesakeCount(namesakeCounter.count(owner));
256	            owner.setHouseholdSize(householdMemberCounter.count(owner));
257	            // A declared household member is knowingly created into a shared household, so it is not
258	            // a suspected duplicate; otherwise fall back to the soft-duplicate signal.
259	            Owner possibleDuplicate = owner.isDeclaredHouseholdMember()
260	                ? null : possibleDuplicateDetector.findPossibleDuplicate(owner);
261	            owner.setPossibleDuplicate(possibleDuplicate != null);
262	            owner.setPossibleDuplicateOf(possibleDuplicate == null ? null : possibleDuplicate.getId());
263	        }
264	        ownerRepository.save(owner);
