291	            return false;
292	        }
293	        // Household members always share a last name (the household id is derived from last name and
294	        // postcode), so narrow by last name, then confirm the household id matches. Soft-deleted
295	        // owners are ignored so a household freed up by a deletion no longer blocks a create.
296	        return ownerRepository.findByLastNameIgnoreCase(owner.getLastName()).stream()
