17	
18	import org.springframework.samples.petclinic.model.CustomerCode;
19	import org.springframework.samples.petclinic.model.Locality;
20	import org.springframework.samples.petclinic.model.Owner;
21	import org.springframework.samples.petclinic.repository.OwnerRepository;
22	import org.springframework.stereotype.Component;
23	
24	/**
25	 * Produces the customer code assigned to a new {@link Owner}.
26	 *
27	 * <p>The code is the owner's {@link CustomerCode} identity {@code '<REGION>-<HASH8>'}: the region
28	 * derived from the owner's postcode (via {@link Locality}, so it disambiguates cities that share a
29	 * name and falls back to the city table) joined to a hash of the owner's normalized telephone and
30	 * last name (e.g. {@code 'NSW-3F2A9C1D'}).
31	 *
32	 * <p>Two owners that share the same normalized telephone and last name would otherwise be assigned
33	 * the same identity, so when the computed code collides with an existing owner's customer code it is
34	 * made unique by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that is still
35	 * free.
36	 */
37	@Component
38	public class CustomerCodeGenerator {
39	
40	    /** Smallest suffix used to disambiguate a colliding customer code. */
41	    private static final int FIRST_SUFFIX = 2;
42	
43	    private final OwnerRepository ownerRepository;
44	
45	    public CustomerCodeGenerator(OwnerRepository ownerRepository) {
46	        this.ownerRepository = ownerRepository;
47	    }
48	
49	    /**
50	     * Generate a unique customer code for the given owner from its region and identity fields.
51	     *
52	     * @param owner the owner being registered
53	     * @return the {@code '<REGION>-<HASH8>'} customer code, de-duplicated with a {@code '-<n>'} suffix
54	     * when it would collide with an existing owner's code
55	     */
56	    public String generate(Owner owner) {
57	        String region = Locality.of(owner.getCity(), owner.getPostcode());
58	        String code = CustomerCode.of(region, owner.getTelephone(), owner.getLastName());
59	        return deduplicate(code);
60	    }
61	
62	    /**
63	     * Return {@code code} unchanged when no owner holds it, otherwise the first {@code '<code>-<n>'}
64	     * variant (starting at {@code n = 2}) that no owner holds yet.
65	     */
66	    private String deduplicate(String code) {
67	        if (!ownerRepository.existsByCustomerCode(code)) {
68	            return code;
69	        }
70	        for (int n = FIRST_SUFFIX; ; n++) {
71	            String candidate = code + "-" + n;
72	            if (!ownerRepository.existsByCustomerCode(candidate)) {
73	                return candidate;
74	            }
75	        }
76	    }
77	}
