24	/**
25	 * Validates that an owner supplies every mandatory field. A field is considered
26	 * missing when it is {@code null} or contains only whitespace. The address is
27	 * satisfied by either the structured {@code addressLine1} or the flat {@code address}.
28	 */
29	public final class OwnerFieldsValidator {
30	
31	    private OwnerFieldsValidator() {
32	    }
33	
34	    /**
35	     * Returns the names of every mandatory field that is missing or blank, in declaration order.
36	     * An owner must supply an address in either form (a non-blank {@code addressLine1} or the flat
37	     * {@code address}); when neither is present {@code address} is reported missing.
38	     *
39	     * @param ownerFields the submitted owner fields
40	     * @return the names of the missing fields, or an empty list when all are present
41	     */
42	    public static List<String> findMissingFields(OwnerFieldsDto ownerFields) {
43	        List<String> missing = new ArrayList<>();
44	        if (isBlank(ownerFields.getFirstName())) {
45	            missing.add("firstName");
46	        }
47	        if (isBlank(ownerFields.getLastName())) {
48	            missing.add("lastName");
49	        }
50	        if (isBlank(ownerFields.getAddressLine1()) && isBlank(ownerFields.getAddress())) {
51	            missing.add("address");
52	        }
53	        if (isBlank(ownerFields.getCity())) {
54	            missing.add("city");
55	        }
56	        if (isBlank(ownerFields.getTelephone())) {
57	            missing.add("telephone");
58	        }
59	        return missing;
60	    }
61	
62	    private static boolean isBlank(String value) {
63	        return value == null || value.isBlank();
64	    }
65	}
