216	        return ResponseEntity.status(status).body(detail);
217	    }
218	
219	    /**
220	     * Handles {@link InvalidPostcodeException} raised when a supplied postcode is out of range for
221	     * its city's region, returning a 400 Bad Request.
222	     *
223	     * @param e The {@link InvalidPostcodeException} to be handled
224	     * @param request {@link HttpServletRequest} object referring to the current request.
225	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
226	     */
227	    @ExceptionHandler(InvalidPostcodeException.class)
228	    @ResponseBody
229	    public ResponseEntity<ProblemDetail> handleInvalidPostcodeException(InvalidPostcodeException e, HttpServletRequest request) {
230	        HttpStatus status = HttpStatus.BAD_REQUEST;
231	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
232	        detail.setProperty("errors", List.of("postcode"));
233	        return ResponseEntity.status(status).body(detail);
234	    }
235	
236	    /**
237	     * Handles {@link DuplicateIdentityException} raised when a new owner's identity key (normalized
238	     * telephone, email and household id) exactly matches that of an existing owner, returning a 409
239	     * Conflict.
240	     *
241	     * @param e The {@link DuplicateIdentityException} to be handled
242	     * @param request {@link HttpServletRequest} object referring to the current request.
243	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
244	     */
245	    /**
